+  --shadow-sm:0 10px 24px rgba(10, 24, 49, .10);
+
+  --primary:#2f5bff; /* electric blue */
+  --primary-2:#1a3cff;
+  --accent:#ff4d6d; /* coral */
+  --accent-2:#21e6a3; /* bright green */
+
+  --radius:18px;
+  --radius-sm:14px;
+  --container:1180px;
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family:Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+  color:var(--text);
+  background:var(--bg);
+  line-height:1.5;
+}
+
+a{color:inherit;text-decoration:none}
+img{max-width:100%;height:auto;display:block}
+
+.container{max-width:var(--container);margin:0 auto;padding:0 20px}
+
+.skip{
+  position:absolute;left:-999px;top:auto;width:1px;height:1px;overflow:hidden;
+}
+.skip:focus{left:20px;top:14px;width:auto;height:auto;z-index:9999;background:#fff;padding:10px 12px;border:1px solid var(--border);border-radius:12px;box-shadow:var(--shadow-sm)}
+
+/* Header */
+.site-header{
+  position:sticky;top:0;z-index:50;
+  background:rgba(255,255,255,.78);
+  backdrop-filter:saturate(160%) blur(10px);
+  border-bottom:1px solid rgba(14,22,43,.08);
+}
+.nav{
+  display:flex;align-items:center;justify-content:space-between;gap:16px;
+  padding:14px 0;
+}
+.brand{display:flex;align-items:center;gap:12px;font-weight:800;letter-spacing:-.02em}
+.brand-mark{
+  width:34px;height:34px;border-radius:12px;
+  background:radial-gradient(100% 100% at 30% 20%, var(--accent-2), transparent 55%),
+             radial-gradient(90% 90% at 80% 30%, var(--accent), transparent 60%),
+             linear-gradient(135deg, var(--primary), var(--primary-2));
+  box-shadow:0 10px 26px rgba(47, 91, 255, .28);
+}
+.brand span{font-size:16px}
+
+.nav-links{display:flex;align-items:center;gap:18px}
+.nav-links a{
+  font-weight:600;font-size:14px;color:rgba(11,15,26,.86);
+  padding:9px 10px;border-radius:999px;
+  transition:background .2s ease, color .2s ease, transform .2s ease;
+}
+.nav-links a:hover{background:rgba(47, 91, 255,.08);color:var(--text)}
+.nav-links a[aria-current="page"]{background:rgba(47, 91, 255,.12)}
+
+.nav-cta{display:flex;align-items:center;gap:10px}
+
+.btn{
+  display:inline-flex;align-items:center;justify-content:center;gap:10px;
+  padding:11px 14px;border-radius:999px;border:1px solid transparent;
+  font-weight:700;font-size:14px;letter-spacing:-.01em;
+  cursor:pointer;user-select:none;
+  transition:transform .18s ease, box-shadow .18s ease, background .18s ease, border-color .18s ease;
+  white-space:nowrap;
+}
+.btn:active{transform:translateY(1px)}
+.btn-primary{
+  background:linear-gradient(135deg, var(--primary), var(--primary-2));
+  color:#fff;
+  box-shadow:0 14px 34px rgba(47, 91, 255,.26);
+}
+.btn-primary:hover{box-shadow:0 18px 46px rgba(47, 91, 255,.32);transform:translateY(-1px)}
+.btn-secondary{
+  background:#fff;color:var(--text);
+  border-color:rgba(14,22,43,.18);
+}
+.btn-secondary:hover{background:rgba(47, 91, 255,.06);border-color:rgba(47, 91, 255,.24);transform:translateY(-1px)}
+.btn-ghost{background:transparent;border-color:rgba(14,22,43,.18)}
+.btn-ghost:hover{background:rgba(14,22,43,.04)}
+
+.nav-toggle{
+  display:none;
+  width:42px;height:42px;border-radius:14px;
+  border:1px solid rgba(14,22,43,.14);background:#fff;cursor:pointer;
+}
+.nav-toggle span{display:block;width:18px;height:2px;background:rgba(11,15,26,.78);margin:4px auto;border-radius:3px}
+
+/* Sections */
+section{padding:80px 0}
+.section-title{font-size:40px;line-height:1.06;letter-spacing:-.03em;margin:0 0 12px}
+.section-sub{color:var(--muted);font-size:16px;max-width:66ch;margin:0}
+
+/* Hero */
+.hero{
+  padding:64px 0 42px;
+  background:
+    radial-gradient(1200px 500px at 20% 0%, rgba(47, 91, 255,.16), transparent 60%),
+    radial-gradient(900px 480px at 90% 15%, rgba(255, 77, 109,.12), transparent 58%),
+    radial-gradient(880px 520px at 70% 85%, rgba(33, 230, 163,.10), transparent 55%);
+}
+.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:28px;align-items:center}
+.hero h1{font-size:56px;line-height:1.0;letter-spacing:-.04em;margin:0 0 14px}
+.hero p{font-size:18px;color:rgba(11,15,26,.78);max-width:62ch;margin:0 0 22px}
+.hero-actions{display:flex;gap:12px;flex-wrap:wrap}
+
+.hero-tabs{
+  background:rgba(255,255,255,.75);
+  border:1px solid rgba(14,22,43,.14);
+  border-radius:var(--radius);
+  box-shadow:var(--shadow-sm);
+  padding:14px;
+}
+.tab-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
+.tab-btn{
+  border-radius:999px;border:1px solid rgba(14,22,43,.14);
+  background:#fff;padding:10px 12px;font-weight:800;font-size:13px;
+  cursor:pointer;transition:background .18s ease,border-color .18s ease,transform .18s ease;
+}
+.tab-btn[aria-selected="true"]{background:rgba(47, 91, 255,.10);border-color:rgba(47, 91, 255,.26)}
+.tab-panel{margin-top:12px}
+
+.preview{
+  border-radius:16px;
+  border:1px solid rgba(14,22,43,.12);
+  background:linear-gradient(180deg, rgba(255,255,255,.9), #fff);
+  box-shadow:0 18px 50px rgba(10, 24, 49, .10);
+  overflow:hidden;
+}
+.preview-top{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;border-bottom:1px solid rgba(14,22,43,.10);background:rgba(14,22,43,.03)}
+.dots{display:flex;gap:6px}
+.dot{width:9px;height:9px;border-radius:50%;background:rgba(11,15,26,.18)}
+.dot:nth-child(1){background:rgba(255, 77, 109,.7)}
+.dot:nth-child(2){background:rgba(33, 230, 163,.7)}
+.dot:nth-child(3){background:rgba(47, 91, 255,.7)}
+.preview-body{padding:16px}
+
+.mini-grid{display:grid;grid-template-columns:1fr;gap:12px}
+.mini-card{border-radius:14px;border:1px solid rgba(14,22,43,.12);padding:12px;background:#fff}
+.mini-title{font-weight:900;letter-spacing:-.02em;margin:0 0 6px}
+.mini-sub{margin:0;color:var(--muted);font-size:13px}
+.mini-bar{height:10px;border-radius:999px;background:rgba(47, 91, 255,.12);overflow:hidden;margin-top:10px}
+.mini-bar > span{display:block;height:100%;width:62%;background:linear-gradient(135deg, var(--primary), var(--primary-2))}
+.mini-list{display:grid;gap:8px;margin-top:10px}
+.mini-row{display:flex;align-items:center;justify-content:space-between;font-size:13px;color:rgba(11,15,26,.78)}
+.pill{font-size:12px;font-weight:800;padding:6px 10px;border-radius:999px;background:rgba(255, 77, 109,.12);color:#8b1027}
+.pill.green{background:rgba(33, 230, 163,.14);color:#0d6b4c}
+
+.stats-bar{
+  padding:22px 0;
+  border-top:1px solid rgba(14,22,43,.10);
+  border-bottom:1px solid rgba(14,22,43,.10);
+  background:linear-gradient(180deg, rgba(47, 91, 255,.06), rgba(255,255,255,0));
+}
+.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
+.stat{
+  border-radius:var(--radius-sm);
+  border:1px solid rgba(14,22,43,.10);
+  background:#fff;
+  padding:16px 18px;
+  box-shadow:0 10px 28px rgba(10, 24, 49, .08);
+}
+.stat strong{display:block;font-size:26px;letter-spacing:-.03em}
+.stat span{display:block;color:var(--muted);font-weight:600;font-size:13px;margin-top:2px}
+
+/* Cards / grids */
+.grid{display:grid;gap:16px}
+.grid-2{grid-template-columns:repeat(2,1fr)}
+.grid-3{grid-template-columns:repeat(3,1fr)}
+.grid-4{grid-template-columns:repeat(4,1fr)}
+
+.card{
+  background:var(--card);
+  border:1px solid rgba(14,22,43,.12);
+  border-radius:var(--radius);
+  padding:18px;
+  box-shadow:0 14px 36px rgba(10, 24, 49, .08);
+}
+.card h3{margin:0 0 8px;font-size:18px;letter-spacing:-.02em}
+.card p{margin:0;color:var(--muted)}
+.kicker{
+  display:inline-flex;align-items:center;gap:10px;
+  font-weight:900;font-size:12px;letter-spacing:.08em;text-transform:uppercase;
+  color:rgba(11,15,26,.72);
+}
+.kicker::before{content:"";width:10px;height:10px;border-radius:4px;background:linear-gradient(135deg,var(--accent),var(--accent-2))}
+
+.icon{
+  width:40px;height:40px;border-radius:14px;
+  background:linear-gradient(135deg, rgba(47, 91, 255,.14), rgba(255, 77, 109,.12));
+  border:1px solid rgba(14,22,43,.10);
+  display:grid;place-items:center;
+}
+.icon svg{width:18px;height:18px}
+
+/* Tabs (Why Choose Us) */
+.tabs{
+  margin-top:18px;
+  border:1px solid rgba(14,22,43,.12);
+  border-radius:var(--radius);
+  background:#fff;
+  box-shadow:var(--shadow-sm);
+  overflow:hidden;
+}
+.tabs-header{display:flex;gap:0;border-bottom:1px solid rgba(14,22,43,.10);flex-wrap:wrap}
+.tabs-header button{
+  appearance:none;border:0;background:transparent;cursor:pointer;
+  padding:14px 16px;font-weight:900;font-size:13px;letter-spacing:-.01em;
+  color:rgba(11,15,26,.76);
+}
+.tabs-header button[aria-selected="true"]{color:var(--text);background:rgba(47, 91, 255,.08)}
+.tabs-body{padding:18px}
+.tabs-body ul{margin:0;padding-left:18px;color:rgba(11,15,26,.82)}
+.tabs-body li{margin:8px 0}
+
+/* Carousel */
+.carousel{
+  position:relative;
+  margin-top:18px;
+  border-radius:var(--radius);
+  border:1px solid rgba(14,22,43,.12);
+  background:#fff;
+  box-shadow:var(--shadow-sm);
+  overflow:hidden;
+}
+.carousel-track{display:flex;transition:transform .45s cubic-bezier(.2,.8,.2,1);will-change:transform}
+.slide{min-width:100%;padding:22px}
+.quote{font-size:18px;line-height:1.4;letter-spacing:-.01em;margin:0 0 14px}
+.who{display:flex;align-items:center;justify-content:space-between;gap:14px}
+.who strong{font-size:14px}
+.tag{font-size:12px;font-weight:900;padding:7px 10px;border-radius:999px;background:rgba(47, 91, 255,.10);color:rgba(11,15,26,.85)}
+.carousel-controls{
+  position:absolute;right:14px;top:14px;display:flex;gap:10px;z-index:5
+}
+.icon-btn{
+  width:40px;height:40px;border-radius:14px;
+  border:1px solid rgba(14,22,43,.12);
+  background:#fff;cursor:pointer;
+  display:grid;place-items:center;
+  transition:transform .18s ease, background .18s ease;
+}
+.icon-btn:hover{background:rgba(14,22,43,.04);transform:translateY(-1px)}
+.dots-row{display:flex;gap:8px;align-items:center;justify-content:center;padding:12px 0 18px}
+.dot-btn{width:8px;height:8px;border-radius:999px;border:0;background:rgba(11,15,26,.20);cursor:pointer}
+.dot-btn[aria-current="true"]{background:linear-gradient(135deg,var(--primary),var(--primary-2));width:26px}
+
+/* FAQ */
+.faq{margin-top:18px}
+.accordion{display:grid;gap:12px}
+.acc-item{border:1px solid rgba(14,22,43,.12);border-radius:var(--radius-sm);background:#fff;box-shadow:0 10px 22px rgba(10,24,49,.06);overflow:hidden}
+.acc-trigger{
+  width:100%;text-align:left;background:transparent;border:0;cursor:pointer;
+  padding:16px 16px;display:flex;align-items:center;justify-content:space-between;gap:14px;
+  font-weight:900;letter-spacing:-.01em;font-size:14px
+}
+.acc-trigger span{color:rgba(11,15,26,.9)}
+.acc-trigger .chev{transition:transform .18s ease;opacity:.7}
+.acc-trigger[aria-expanded="true"] .chev{transform:rotate(180deg)}
+.acc-panel{height:0;overflow:hidden;transition:height .22s ease}
+.acc-panel > div{padding:0 16px 16px;color:var(--muted)}
+
+/* Logo grid */
+.logo-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-top:18px}
+.logo{
+  border:1px solid rgba(14,22,43,.10);
+  border-radius:16px;background:#fff;
+  padding:14px 12px;
+  display:flex;align-items:center;justify-content:center;
+  font-weight:900;font-size:12px;letter-spacing:-.01em;
+  color:rgba(11,15,26,.82);
+}
+.logo span{display:inline-flex;align-items:center;gap:8px}
+.logo i{width:10px;height:10px;border-radius:3px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:inline-block}
+
+/* Pricing */
+.pricing-grid{margin-top:18px;display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
+.price-card{position:relative;overflow:hidden}
+.price-card .top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
+.price{font-size:30px;font-weight:1000;letter-spacing:-.04em;margin:10px 0 4px}
+.price small{font-size:13px;font-weight:800;color:rgba(11,15,26,.7)}
+.fine{color:var(--muted);font-size:13px;margin:0}
+.badge{
+  font-size:12px;font-weight:1000;
+  padding:7px 10px;border-radius:999px;
+  background:rgba(255, 77, 109,.12);
+  color:#8b1027;
+}
+.badge.blue{background:rgba(47, 91, 255,.10);color:rgba(11,15,26,.88)}
+.price-card ul{margin:14px 0 0;padding-left:18px;color:rgba(11,15,26,.78)}
+.price-card li{margin:8px 0}
+.price-card.popular{
+  border-color:rgba(47, 91, 255,.22);
+  box-shadow:0 20px 60px rgba(47, 91, 255,.18);
+}
+.price-card.popular::before{
+  content:"";position:absolute;inset:-40% -30% auto auto;width:220px;height:220px;
+  background:radial-gradient(circle at 30% 30%, rgba(33,230,163,.35), transparent 60%),
+             radial-gradient(circle at 60% 60%, rgba(255,77,109,.26), transparent 60%),
+             radial-gradient(circle at 40% 70%, rgba(47,91,255,.32), transparent 64%);
+  transform:rotate(22deg);
+}
+
+/* CTA banner */
+.cta{
+  padding:0 0 86px;
+}
+.cta-box{
+  border-radius:28px;
+  border:1px solid rgba(14,22,43,.14);
+  background:
+    radial-gradient(900px 400px at 15% 20%, rgba(47, 91, 255,.20), transparent 60%),
+    radial-gradient(900px 420px at 85% 40%, rgba(255, 77, 109,.15), transparent 60%),
+    linear-gradient(180deg, rgba(255,255,255,.92), #fff);
+  box-shadow:var(--shadow);
+  padding:26px;
+  display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap
+}
+.cta-box h2{margin:0;font-size:28px;letter-spacing:-.03em}
+.cta-box p{margin:8px 0 0;color:rgba(11,15,26,.72)}
+
+/* Footer */
+footer{padding:44px 0;border-top:1px solid rgba(14,22,43,.10);background:rgba(14,22,43,.02)}
+.footer-grid{display:grid;grid-template-columns:1.2fr repeat(4,1fr);gap:18px}
+.footer-grid h4{margin:0 0 10px;font-size:13px;letter-spacing:-.01em}
+.footer-grid a{display:block;padding:6px 0;color:rgba(11,15,26,.72);font-weight:600;font-size:13px}
+.footer-grid a:hover{color:rgba(11,15,26,.92)}
+.footnote{margin-top:18px;color:rgba(11,15,26,.60);font-size:12px}
+
+/* Animations */
+.reveal{opacity:0;transform:translateY(10px);transition:opacity .6s ease, transform .6s ease}
+.reveal.is-visible{opacity:1;transform:none}
+
+/* Utilities */
+.mt-14{margin-top:14px}
+.mt-22{margin-top:22px}
+.center{text-align:center}
+.max-62{max-width:62ch;margin-left:auto;margin-right:auto}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns:1fr;}
+  .hero h1{font-size:44px}
+  .stats{grid-template-columns:1fr}
+  .grid-3{grid-template-columns:1fr}
+  .grid-4{grid-template-columns:repeat(2,1fr)}
+  .pricing-grid{grid-template-columns:repeat(2,1fr)}
+  .logo-grid{grid-template-columns:repeat(3,1fr)}
+  .footer-grid{grid-template-columns:1fr 1fr}
+  section{padding:66px 0}
+  .nav-toggle{display:grid;place-items:center}
+  .nav-links{display:none}
+  .site-header[data-open="true"] .nav-links{
+    display:flex;
+    position:absolute;left:20px;right:20px;top:62px;
+    background:#fff;border:1px solid rgba(14,22,43,.12);
+    border-radius:18px;padding:12px;
+    box-shadow:var(--shadow-sm);
+    flex-direction:column;align-items:stretch
+  }
+  .site-header[data-open="true"] .nav-links a{padding:12px 12px}
+}
+
+@media (max-width: 560px){
+  .hero h1{font-size:38px}
+  .pricing-grid{grid-template-columns:1fr}
+  .logo-grid{grid-template-columns:repeat(2,1fr)}
+}
*** End Patch
PATCH

