import re, pathlib
root=pathlib.Path('/app/output')
htmls=list(root.glob('*.html'))
issues=[]
for p in htmls:
  s=p.read_text('utf-8')
  # ensure nav includes all pages
  nav=re.search(r'<nav class="nav-links"[\s\S]*?</nav>', s)
  if not nav:
    issues.append((p.name,'no nav'))
    continue
  n=nav.group(0)
  for href in ['online-courses.html','digital-downloads.html','memberships.html','coaching.html']:
    if href not in n:
      issues.append((p.name,f'missing link {href}'))
# check FAQ accordion requirement: FAQ on 4/5 pages (home, courses, downloads, coaching). memberships no FAQ.
for p in htmls:
  has_faq='data-accordion' in p.read_text('utf-8')
  if p.name in ['index.html','online-courses.html','digital-downloads.html','coaching.html'] and not has_faq:
    issues.append((p.name,'expected faq missing'))
  if p.name=='memberships.html' and has_faq:
    issues.append((p.name,'faq should be absent per spec'))
print('OK' if not issues else '\n'.join(map(str,issues)))
PY"}
